/* Responsive, semantic home and asset library. Shared catalogue/state with the design prototype. */

window.RMChrome=(()=>{const mark='<svg viewBox="0 0 32 36" aria-hidden="true"><path fill="#dce4ec" d="M2 7 16 0l14 8-14 8Z"/><path fill="#7995ad" d="m2 7 14 9v20L2 28Z"/><path fill="#477da4" d="m16 16 14-8v14l-7 4 7 10H19L9 22Z"/><path fill="#c4ccd3" d="m16 16 7 4 7-4v6l-7 4-7-4Z"/></svg>';return '<header class="wc-header"><a class="wc-wordmark" href="#home">'+mark+'<span>RenderMarket</span></a><nav aria-label="Main navigation"><details><summary>Products</summary><div><a href="#explore">Asset catalogue</a><a href="asset.html?id=sanctuary">3D viewer</a></div></details><details><summary>Features</summary><div><a href="asset.html?id=sanctuary#technical">Model inspection</a><a href="asset.html?id=sanctuary#files">File formats</a></div></details><details><summary>Developers</summary><div><a href="#register">Creator workflow</a><a href="https://github.com/Fioye3D/render-market">Source code</a></div></details><details><summary>Resources</summary><div><a href="terms.html">Terms of Use</a><a href="privacy.html">Privacy Policy</a></div></details><a class="wc-current" href="#explore">Assets</a><a href="#explore">Pricing</a></nav><a class="wc-search-link" href="#explore" aria-label="Search catalogue"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg></a><a class="wc-login" href="#register" title="Account workflow demonstration; authentication is not connected">Log in</a><a class="wc-get" href="#explore">Explore RenderMarket</a></header>';})();
window.RMFooter="<footer class=\"wc-footer\"><div class=\"wc-footer-brand\"><a href=\"#home\">RenderMarket</a><p>English</p><p>\u00a9 2026 RenderMarket</p><small>Independent UI/UX project</small></div><div><strong>Products</strong><a href=\"#explore\">Asset library</a><a href=\"asset.html?id=sanctuary\">3D viewer</a></div><div><strong>Features</strong><a href=\"asset.html?id=sanctuary#technical\">Model inspection</a><a href=\"asset.html?id=sanctuary#files\">File formats</a></div><div><strong>Catalogue</strong><a href=\"#explore?search=rural%20worlds\">Rural Worlds</a><a href=\"#explore?search=lagos%20everyday\">Everyday Lagos</a></div><div><strong>Developers</strong><a href=\"#register\">Creator workflow</a><a href=\"https://github.com/Fioye3D/render-market\">GitHub</a></div><div><strong>Resources</strong><a href=\"#foundations\">Design system</a><a href=\"#brand\">Identity</a></div><div><strong>Legal</strong><a href=\"privacy.html\">Privacy Policy</a><a href=\"terms.html\">Terms of Use</a></div></footer>";

window.renderMarketplace=(page,{state,matches,go,action})=>{

 const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

 const count=type=>RM_ASSETS.filter(a=>a.cat===type).length;

 const mark='<svg viewBox="0 0 32 36" aria-hidden="true"><path fill="#dce4ec" d="M2 7 16 0l14 8-14 8Z"/><path fill="#7995ad" d="m2 7 14 9v20L2 28Z"/><path fill="#477da4" d="m16 16 14-8v14l-7 4 7 10H19L9 22Z"/><path fill="#c4ccd3" d="m16 16 7 4 7-4v6l-7 4-7-4Z"/></svg>';

 const search=(label,hero=false)=>'<form class="m-search '+(hero?'m-search-hero':'')+'" role="search"><input class="m-search-field" aria-label="'+label+'" value="'+e(state.fields.search||'')+'" placeholder="'+(hero?'Search models, materials and scenes':'Search the library')+'" autocomplete="off"><button aria-label="'+(hero?'Search library':'Submit search')+'">'+(hero?'Search assets':'Search')+'</button></form>';

 let previewIndex=0; const card=a=>'<article class="m-card"><div class="m-card-preview"><a href="asset.html?id='+a.id+'" aria-label="View '+e(a.title)+'"><img loading="'+(previewIndex++<8?'eager':'lazy')+'" decoding="async" width="560" height="420" src="../assets/thumbnails/'+a.file+'.webp" alt="'+e(a.title)+'"></a><button class="m-save" data-save="'+a.id+'" aria-label="'+(state.saved.has(a.id)?'Remove saved ':'Save ')+e(a.title)+'" aria-pressed="'+state.saved.has(a.id)+'">'+(state.saved.has(a.id)?'-':'+')+'</button></div><div class="m-card-info"><a class="m-card-title" href="asset.html?id='+a.id+'">'+e(a.title)+'</a><a class="m-card-creator" href="#'+a.creatorRoute+'">'+e(a.creator)+' <span>↗</span></a><div class="m-card-meta"><span>BLEND · GLB</span><strong>'+(a.price===null?'Portfolio scene':'₦'+a.price.toLocaleString('en-NG'))+'</strong></div><div class="m-card-place">'+(a.collection==='rural-worlds'?'Procedural study · ':'')+e(a.placeLabel||a.region||'Object study')+'</div></div></article>';

 const radio=(group,label,value,selected)=>'<label class="m-option"><input type="radio" name="'+group+'" value="'+e(value)+'" '+(selected?'checked':'')+'><span>'+e(label)+'</span></label>';

 const nav=window.RMChrome;


 const categories=[['Models & props','3D models',count('3D models')],['Materials & textiles','Materials',count('Materials')],['Environments','Environments',count('Environments')],['All assets','All assets',RM_ASSETS.length]];

 let content='';


 if(page==='home'){
 content=`<div class="wc-columns"><div class="wc-content"><section class="wc-app"><div class="wc-app-identity"><img src="../assets/logo/logo-dark.svg" width="128" height="128" alt="RenderMarket"><div><h1>RenderMarket</h1><a href="https://github.com/Fioye3D/render-market">github.com/Fioye3D</a><a class="wc-category" href="#explore">3D assets</a></div></div><div class="wc-actions"><a href="#explore" class="wc-download">Explore the marketplace</a><a href="asset.html?id=sanctuary" class="wc-secondary">Open the 3D viewer</a></div></section><p class="wc-summary">RenderMarket is a digital asset marketplace concept for African 3D creators, featuring models, materials and environments with interactive scene previews.</p><p class="wc-owner">An independent project by Adefioye Favour. <a href="#creator:owner">View creator profile</a> to explore the featured work.</p><section class="wc-promo" aria-label="Explore RenderMarket"><p>Discover original 3D work and African creative worlds with RenderMarket.</p><ul><li>Browse scenes, models and materials across ${RM_ASSETS.length} catalogue listings.</li><li>Inspect actual geometry in the browser with camera and wireframe controls.</li><li>Review file formats, creator information and technical details before choosing an asset.</li></ul><a href="#explore">Learn more about the asset library <span aria-hidden="true">→</span></a></section><section class="wc-description"><p>RenderMarket is a self-initiated UI/UX portfolio project that connects African creative perspectives with a digital asset marketplace. Its catalogue brings together contemporary Lagos settings, rural environments, agricultural scenes, objects and material studies.</p><p>Each asset listing provides a rendered preview, technical information and a browser-based 3D inspection tool where available. Sanctuary Temple is the featured original scene by Adefioye Favour. Other listings include clearly labelled procedural studies created during this project.</p><p>Search by subject or explore the collections to find village scenes, farms, markets, architecture and everyday objects. Proposed catalogue prices are shown for presentation; Sanctuary Temple has an owner-set price of ₦300,000. Purchasing, authentication and protected delivery are not connected yet.</p><p class="wc-taxonomy">Categories: <button data-category="3D models">3D models</button><button data-category="Materials">Materials</button><button data-category="Environments">Environments</button></p><p class="wc-disclaimer">Portfolio prototype. Sample listings do not establish a purchase agreement. Purchasing, accounts and protected delivery are being prepared.</p></section><section class="wc-related"><h2>RenderMarket collections</h2><div class="wc-tiles">${['rural-village','royal-courtyard','river-landscape','yam-farm','cocoa-farm','maize-farm','cattle-ranch','courtyard-mosque'].map(id=>{const a=RM_ASSETS.find(x=>x.id===id);return '<a href="asset.html?id='+a.id+'"><img loading="lazy" decoding="async" src="../assets/icons/'+a.file+'.webp" width="80" height="80" alt=""><span>'+e(a.title)+'</span></a>'}).join('')}</div></section><section class="wc-related"><h2>Related assets</h2><div class="wc-tiles">${['sanctuary','orbit','loop','kente','baobab','canteen','barbershop','herbalist-shrine'].map(id=>{const a=RM_ASSETS.find(x=>x.id===id);return '<a href="asset.html?id='+a.id+'"><img loading="lazy" decoding="async" src="../assets/icons/'+a.file+'.webp" width="80" height="80" alt=""><span>'+e(a.title)+'</span></a>'}).join('')}</div></section></div><aside class="wc-sidebar"><a class="wc-sidebar-card" href="asset.html?id=sanctuary"><img src="../assets/previews/sanctuary-temple-480.webp" width="480" height="270" alt="Sanctuary Temple"><div><span>Featured environment</span><h2>A world worth a closer look.</h2><p>Explore Sanctuary Temple, an original Blender scene by Adefioye Favour.</p><strong>Inspect in 3D <span aria-hidden="true">→</span></strong></div></a></aside></div>`;
 }else{

  const list=page==='saved'?RM_ASSETS.filter(a=>state.saved.has(a.id)):matches();

  content='<section class="m-library-heading"><p class="m-eyebrow">ASSET LIBRARY</p><h1>Explore assets</h1><p class="m-muted">Models, materials and environments with downloadable source files.</p>'+search('Search assets',true)+'<div class="m-suggestions"><span>Browse</span><button data-query="lagos everyday">Everyday Lagos · 10 assets</button><button data-query="characters">With characters</button></div></section><div class="m-library"><aside class="m-filters"><div class="m-filter-heading"><strong>Filters</strong><button data-reset>Reset</button></div><fieldset><legend>Asset type</legend>'+['All assets','3D models','Materials','Environments'].map(c=>radio('category',c,c,state.category===c)).join('')+'</fieldset><fieldset><legend>Price</legend>'+[['Any price',0],['Under ₦10,000',1],['₦10,000 and above',2]].map(([label,v])=>radio('price',label,v,state.price===v)).join('')+'</fieldset><fieldset><legend>Place reference</legend>'+['All places','Nigeria','Ghana','Mali','Tanzania','Kenya','Guinea','Senegal'].map(c=>radio('region',c,c,state.region===c)).join('')+'</fieldset><div class="m-compatibility"><span>Source software</span><strong>Blender 4.2</strong><small>Portable GLB, OBJ and FBX exports are listed on each asset page.</small></div></aside><section class="m-results" aria-label="Asset results"><div class="m-results-header"><strong role="status">'+list.length+' '+(list.length===1?'asset':'assets')+'</strong><label>Sort by <select aria-label="Sort assets"><option value="featured" '+(state.sort==='featured'?'selected':'')+'>Featured</option><option value="price-asc" '+(state.sort==='price-asc'?'selected':'')+'>Price: low to high</option><option value="price-desc" '+(state.sort==='price-desc'?'selected':'')+'>Price: high to low</option></select></label></div>'+(list.length?'<div class="m-grid">'+list.map(card).join('')+'</div>':'<div class="m-empty"><h2>No matching assets</h2><p>Try a different search or reset the filters.</p><button data-reset>Reset filters</button></div>')+'</section></div>';

 }

 document.body.dataset.page=page;const root=document.querySelector('#artboard');root.classList.add('native-artboard');root.classList.toggle('mobile',state.forcedMobile);root.innerHTML='<div class="m-shell">'+nav+'<div class="m-main">'+content+''+window.RMFooter+'</div><nav class="m-mobile-nav" aria-label="Mobile navigation"><a href="#home" '+(page==='home'?'aria-current="page"':'')+'>Home</a><a href="#explore" '+(page==='explore'?'aria-current="page"':'')+'>Explore</a><a href="#saved">Saved '+state.saved.size+'</a><a href="#register">Creator studio</a></nav></div>';

 root.querySelectorAll('.m-search').forEach(form=>form.onsubmit=event=>{event.preventDefault();state.fields.search=form.querySelector('.m-search-field').value;go('explore')});

 root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>action('save:'+b.dataset.save));

 root.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>action('query:'+b.dataset.query));

 root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.fields.search='';state.region='All places';state.price=0;action('category:'+b.dataset.category)});

 root.querySelectorAll('input[type=radio]').forEach(input=>input.onchange=()=>{state[input.name]=input.name==='price'?Number(input.value):input.value;window.renderMarketplace(page,{state,matches,go,action})});

 const sort=root.querySelector('select');if(sort)sort.onchange=()=>{state.sort=sort.value;window.renderMarketplace(page,{state,matches,go,action})};

 root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{state.fields.search='';state.region='All places';state.category='All assets';state.price=0;state.sort='featured';history.replaceState(null,'','#explore');window.renderMarketplace(page,{state,matches,go,action})});

 document.querySelector('#screen-title').textContent=page==='home'?'RenderMarket marketplace':'Explore assets';document.title=(page==='home'?'RenderMarket':'Explore assets')+' | 3D asset portfolio';

};
